treatmentCSS:
[data-visual-theme="reference-editor"] { --pyre-radius:8px; --pyre-section-gap:20px; --pyre-row-pad:14px; --pyre-content-width:1180px; --pyre-reading-width:68ch; }
[data-visual-theme="reference-editor"] body { line-height:1.55; }
[data-visual-theme="reference-editor"] h1 { font-size:26px; font-weight:650; letter-spacing:-.01em; }
[data-visual-theme="reference-editor"] .page-header { padding-bottom:20px; }
[data-visual-theme="reference-editor"] .palette-heading { font-size:18px; font-weight:650; }
[data-visual-theme="reference-editor"] .theme-picker-label { margin-top:16px; }
[data-visual-theme="reference-editor"] .refinement-selected { margin-top:16px; }
[data-visual-theme="reference-editor"] .theme-number { font-size:14px; opacity:1; }
[data-visual-theme="reference-editor"] button, [data-visual-theme="reference-editor"] .button { border-radius:8px; background:var(--pyre-raised); border-color:var(--pyre-control-border,var(--pyre-border)); color:var(--pyre-text); }
[data-visual-theme="reference-editor"] button:hover { background:var(--pyre-surface); }
[data-visual-theme="reference-editor"] button[aria-pressed="true"] { background:var(--pyre-sidebar-selection,var(--pyre-accent-soft)); color:var(--pyre-text); border-color:var(--pyre-accent); box-shadow:inset 0 -2px var(--pyre-accent); }
[data-visual-theme="reference-editor"] button.primary { background:var(--pyre-action,var(--pyre-accent)); border-color:var(--pyre-action,var(--pyre-accent)); color:var(--pyre-on-action,var(--pyre-accent-text)); box-shadow:none; }
[data-visual-theme="reference-editor"] :focus-visible { outline:2px solid var(--pyre-focus); outline-offset:2px; }
[data-visual-theme="reference-editor"] .quick-controls { background:var(--pyre-canvas); padding:8px 0; border-color:var(--pyre-line); }
[data-visual-theme="reference-editor"] .appearance-pickers { border:1px solid var(--pyre-line); border-radius:10px; background:var(--pyre-surface); padding:16px; margin-bottom:12px; }
[data-visual-theme="reference-editor"] .appearance-pickers .palette-option { flex-basis:9em; gap:6px; }
[data-visual-theme="reference-editor"] .appearance-pickers .palette-option .swatch { border-color:var(--pyre-line); border-radius:4px; height:16px; }
[data-visual-theme="reference-editor"] .appearance-pickers .theme-option { min-height:44px; font-size:15px; }
[data-visual-theme="reference-editor"] .appearance-details { border:1px solid var(--pyre-line); background:var(--pyre-surface); border-radius:10px; padding:0 16px; margin-top:12px; }
[data-visual-theme="reference-editor"] .appearance-details .controls { padding-bottom:16px; border-bottom:0; }
[data-visual-theme="reference-editor"] #plan > .plan-section { background:var(--pyre-surface); border:1px solid var(--pyre-line); border-radius:10px; padding:18px; margin-top:20px; box-shadow:none; }
[data-visual-theme="reference-editor"] #plan h2 { font-size:20px; font-weight:650; letter-spacing:0; }
[data-visual-theme="reference-editor"] #plan h3 { font-size:18px; font-weight:650; }
[data-visual-theme="reference-editor"] #plan > .plan-section > .section-heading { border:0; padding:0 16px 0 0; }
[data-visual-theme="reference-editor"] #plan > .plan-section > .section-body { border:0; padding-left:0; }
[data-visual-theme="reference-editor"] #plan .pr-list li { padding:14px 0; border-bottom:1px solid var(--pyre-line); }
[data-visual-theme="reference-editor"] #plan .pr-list li:last-child { border-bottom:0; }
[data-visual-theme="reference-editor"] #plan .pr-list .mono { background:var(--pyre-code,var(--pyre-raised)); color:var(--pyre-text); border:1px solid var(--pyre-line); border-radius:6px; padding:4px 6px; font-size:14px; line-height:1.4; align-self:start; width:fit-content; }
[data-visual-theme="reference-editor"] #plan .pr-list p { margin-top:6px; }
[data-visual-theme="reference-editor"] #plan .notice { background:var(--pyre-subtle,var(--pyre-accent-soft)); color:var(--pyre-text); border:1px solid var(--pyre-line); border-radius:8px; padding:14px 16px; }
[data-visual-theme="reference-editor"] #plan .notice .muted { color:var(--pyre-text); }
[data-visual-theme="reference-editor"] #plan .evidence li { padding:10px 0; }
[data-visual-theme="reference-editor"] .output { background:var(--pyre-code,var(--pyre-surface)); color:var(--pyre-text); border-color:var(--pyre-functional-border,var(--pyre-border)); border-radius:8px; }
[data-visual-theme="reference-editor"] .token { border-color:var(--pyre-line); }
@media(max-width:850px) {
 [data-visual-theme="reference-editor"] #plan > .plan-section > .section-heading { border:0; padding:0; }
 [data-visual-theme="reference-editor"] #plan > .plan-section > .section-body { border:0; padding:0; }
 [data-visual-theme="reference-editor"] #plan .pr-list .mono { padding:4px 6px; border:1px solid var(--pyre-line); }
}
@media(max-width:720px) {
 [data-visual-theme="reference-editor"] .page { padding:20px 16px 48px; }
 [data-visual-theme="reference-editor"] .appearance-pickers { padding:12px; }
 [data-visual-theme="reference-editor"] #plan > .plan-section { padding:14px 12px; }
 [data-visual-theme="reference-editor"] .appearance-details { padding:0 12px; }
 [data-visual-theme="reference-editor"] #plan .notice { padding:12px; }
}
/* Keep technical ranges whole; grow the gutter with its actual text. */
[data-visual-theme="reference-editor"][data-style="moss"] #plan .pr-list li { grid-template-columns:max-content minmax(0,1fr); }
[data-visual-theme="reference-editor"] #plan .pr-list .mono { white-space:nowrap; width:max-content; min-width:max-content; }
@container pyre-margin (max-width:calc(10.5em + 28px)) {
 [data-visual-theme="reference-editor"][data-style="moss"] #plan .pr-list li { grid-template-columns:minmax(0,1fr); }
 [data-visual-theme="reference-editor"][data-style="moss"] #plan .pr-list .mono { grid-column:1; grid-row:1; }
 [data-visual-theme="reference-editor"][data-style="moss"] #plan .pr-list li > div { grid-column:1; grid-row:2; }
 [data-visual-theme="reference-editor"][data-style="moss"] #plan .pr-state { grid-column:1; grid-row:3; }
}
@media(max-width:380px) {
 /* At ordinary text size these remain12px. Enlarged text gets reading space back. */
 [data-visual-theme="reference-editor"] #plan > .plan-section { padding-inline:clamp(6px,calc(100vw - 10em),12px); }
 [data-visual-theme="reference-editor"] #plan .notice { padding-inline:clamp(8px,calc(100vw - 10em),12px); }
}
@media print {
 :root { --pyre-action:#333333 !important; --pyre-on-action:#ffffff !important; --pyre-code:#ffffff !important; --pyre-subtle:#eeeeee !important; --pyre-functional-border:#777777 !important; --pyre-control-border:#777777 !important; }
}

