  --pyre-accent: #a99acb;
  --pyre-action: #d7a6bd;
  --pyre-message: #443c55;
  --pyre-code: #131318;
  --pyre-sidebar: #131318;
  --pyre-sidebar-controls: #332f3c;
  --pyre-sidebar-selection: #393345;
  --pyre-terminal: #19191e;
