  --pyre-canvas: #19191e;
  --pyre-accent-soft: #342e42;
  --pyre-accent-text: #131318;
  --pyre-accent-secondary: #d7a6bd;
  --pyre-line: #55525f;
  --pyre-functional-border: #a99acb;
  --pyre-control-border: #918d9a;
}

[data-palette="reference-charcoal-violet"][data-mode="light"] {
  color-scheme:light;
  --pyre-background: #f3f1f7;
