  --pyre-accent-text: #fbfaff;
  --pyre-accent-secondary: #844463;
  --pyre-line: #7e708a;
  --pyre-functional-border: #7e708a;
  --pyre-control-border: #7e708a;
}

[data-mode="light"][data-base="neutral"] { --pyre-canvas:#f3f5f6; --pyre-surface:#ffffff; --pyre-raised:#e9edf0; --pyre-line:#d3d8dc; }
[data-mode="dark"][data-base="neutral"] { --pyre-canvas:#10151a; --pyre-surface:#181f26; --pyre-raised:#242d36; --pyre-line:#394149; }
